<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { BellRing, Bot, Clock3, Eye, MousePointer2, Quote, RotateCw, Save, Sparkles } from 'lucide-vue-next'
import AppButton from '../components/ui/AppButton.vue'
import AppCard from '../components/ui/AppCard.vue'
import AppTabs from '../components/ui/AppTabs.vue'
import InlineStatus, { type InlineStatusState } from '../components/ui/InlineStatus.vue'
import { useAuthStore } from '../stores/auth'
import { useContextStore } from '../stores/context'
import { usePreferencesStore } from '../stores/preferences'
import { useLegacyMutationRuntime } from '../features/shared/useLegacyMutationRuntime'
import { saveSettingsMutation } from '../features/settings/settings-mutations'

const auth=useAuthStore(),context=useContextStore(),preferences=usePreferencesStore(),createRuntime=useLegacyMutationRuntime()
const activeTab=ref('general'),saving=ref(false),status=ref<InlineStatusState>('idle'),statusMessage=ref('')
const tabs=[{id:'general',label:'Chung & đăng ký'},{id:'ai',label:'AI duyệt'},{id:'owl',label:'Cú Thông Thái'}]
const announcement=ref(''),registrationDeadlineTime=ref('20:00'),aiAutoApproveThreshold=ref(90),smartApprovalEnabled=ref(true)
const settings=computed(()=>auth.legacyState?.settings??{})
const memory=computed<Record<string,unknown>>(()=>((auth.legacyState?.aiFeedbackMemoryStats as Record<string,unknown>|undefined)??{}))
const revisionThreshold=computed(()=>Math.round(Number(settings.value.aiRevisionActionThreshold??.85)*100))
function hydrate(){announcement.value=String(settings.value.announcement??'');registrationDeadlineTime.value=String(settings.value.registrationDeadlineTime??'20:00');aiAutoApproveThreshold.value=Math.round(Number(settings.value.aiAutoApproveThreshold??.9)*100);smartApprovalEnabled.value=Boolean(settings.value.aiAutomationEnabled??settings.value.smartApprovalEnabled??settings.value.aiReviewEnabled??true)}
watch(settings,hydrate,{immediate:true})
async function save(){if(!context.selectedClassId)return;saving.value=true;status.value='idle';try{await saveSettingsMutation(createRuntime(),context.selectedClassId,{announcement:announcement.value,registrationDeadlineTime:registrationDeadlineTime.value,aiAutomationEnabled:smartApprovalEnabled.value,aiAutoApproveThreshold:aiAutoApproveThreshold.value/100});status.value='success';statusMessage.value=`Đã lưu cài đặt. Deadline tự động: ${registrationDeadlineTime.value}.`}catch(error){status.value='error';statusMessage.value=error instanceof Error?error.message:'Không lưu được cài đặt.'}finally{saving.value=false}}
</script>
<template><div class="page-stack settings-page"><header><span>CẤU HÌNH ỨNG DỤNG</span><h1>Cài đặt</h1><p>Cấu hình lớp học, đăng ký, AI và trải nghiệm Cú Thông Thái.</p></header><AppTabs v-model="activeTab" :items="tabs" label="Nhóm cài đặt"/><InlineStatus :state="status" :message="statusMessage"/>
<form @submit.prevent="save"><AppCard v-if="activeTab==='general'" padding="lg" class="settings-card"><div class="section-title"><Clock3/><div><span>THÔNG TIN LỚP</span><h2>Thiết lập chung</h2></div></div><div class="field-grid"><label>Tên lớp<input :value="String(settings.className??context.selectedClass?.name??'')" readonly></label><label>Năm học<input :value="String(settings.schoolYear??'')" readonly></label><label>Mốc deadline tự động<input v-model="registrationDeadlineTime" type="time" step="60"><small>Áp dụng cho chế độ “tối hôm trước từng buổi”.</small></label><label class="wide">Thông báo tuần<textarea v-model="announcement" rows="4"/></label></div><div class="periods"><span v-for="period in auth.legacyState?.periods??[]" :key="period.n"><b>Tiết {{ period.n }}</b><small>{{ period.start }} – {{ period.end }}</small></span></div></AppCard>
<AppCard v-else-if="activeTab==='ai'" padding="lg" class="settings-card"><div class="section-title"><Bot/><div><span>TỰ ĐỘNG HÓA</span><h2>Duyệt đăng ký bằng AI</h2></div></div><label class="toggle"><input v-model="smartApprovalEnabled" type="checkbox"><span><b>Duyệt tự động bằng AI</b><small><strong>Bật:</strong> Groq kiểm tra đăng ký mới/gửi lại và học từ phản hồi GV.</small><small><strong>Tắt:</strong> Mọi đăng ký chuyển GV duyệt.</small></span></label><div class="threshold"><div><b>Ngưỡng AI được tự duyệt</b><small>AI dưới ngưỡng này luôn chuyển GV.</small></div><strong>{{ aiAutoApproveThreshold }}%</strong><input v-model.number="aiAutoApproveThreshold" type="range" min="80" max="99" step="1"></div><p class="explain">Đăng ký mới dùng ngưỡng <b>{{ aiAutoApproveThreshold }}%</b>. Khi học sinh sửa theo phản hồi GV, AI chỉ tự hành động khi độ chắc chắn đạt <b>{{ revisionThreshold }}%</b>; trường hợp không chắc chuyển giáo viên.</p><div class="memory"><span><small>Phản hồi đã ghi nhận</small><b>{{ Number(memory.totalFeedback??0) }}</b></span><span><small>AI duyệt → GV yêu cầu sửa</small><b>{{ Number(memory.revisionAfterAiApprove??0) }}</b></span><span><small>AI chuyển GV → GV duyệt</small><b>{{ Number(memory.approveAfterAiManual??0) }}</b></span><span><small>AI yêu cầu sửa → GV duyệt</small><b>{{ Number(memory.approveAfterAiRevision??0) }}</b></span></div></AppCard>
<AppCard v-else padding="lg" class="settings-card owl-settings"><div class="section-title"><Sparkles/><div><span>TRỢ LÝ TRONG APP</span><h2>Cú Thông Thái</h2></div></div><p class="owl-intro">Chọn cách Cú xuất hiện và tương tác. Các tùy chọn này áp dụng ngay trên thiết bị hiện tại.</p><div class="owl-options">
<label class="owl-option"><span class="option-icon violet"><Eye/></span><span><b>Hiện Cú Thông Thái</b><small>Ẩn hoàn toàn Cú nếu bạn muốn giao diện tối giản hơn.</small></span><input v-model="preferences.owlEnabled" type="checkbox"></label>
<label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon sky"><MousePointer2/></span><span><b>Mắt theo con trỏ</b><small>Đồng tử di chuyển nhẹ theo vị trí chuột.</small></span><input v-model="preferences.owlFollowPointer" type="checkbox" :disabled="!preferences.owlEnabled"></label>
<label class="owl-option" :class="{disabled:!preferences.owlEnabled||!preferences.owlFollowPointer}"><span class="option-icon mint"><RotateCw/></span><span><b>Nghiêng đầu theo con trỏ</b><small>Đầu nghiêng tối đa ±5° để chuyển động tự nhiên.</small></span><input v-model="preferences.owlHeadTilt" type="checkbox" :disabled="!preferences.owlEnabled||!preferences.owlFollowPointer"></label>
<label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon coral"><BellRing/></span><span><b>Tự mở cảnh báo cần chú ý</b><small>Tự bật lời nhắc khi còn đăng ký hoặc thông báo cần xử lý.</small></span><input v-model="preferences.owlAutoOpenUrgent" type="checkbox" :disabled="!preferences.owlEnabled"></label>
<label class="owl-option" :class="{disabled:!preferences.owlEnabled}"><span class="option-icon sun"><Quote/></span><span><b>Luân phiên danh ngôn</b><small>Cho Cú hiển thị danh ngôn sau các lời nhắc theo ngữ cảnh.</small></span><input v-model="preferences.owlQuotesEnabled" type="checkbox" :disabled="!preferences.owlEnabled"></label>
</div><div class="instant-note">✓ Cài đặt Cú được lưu tự động trên trình duyệt này.</div></AppCard>
<div v-if="activeTab!=='owl'" class="save-bar"><span>Mọi thay đổi chỉ được lưu khi bấm nút bên cạnh.</span><AppButton type="submit" :loading="saving"><Save/>Lưu cài đặt</AppButton></div></form></div></template>
<style scoped>.settings-page{max-width:1200px;margin:0 auto}.settings-page>header span,.section-title span{color:var(--color-primary);font-size:.78rem;font-weight:850;letter-spacing:.08em}.settings-page>header h1{margin:7px 0;font-size:clamp(2rem,4vw,3rem)}.settings-page>header p{color:var(--text-muted)}form{display:grid;gap:16px}.section-title{display:flex;gap:12px;align-items:center;margin-bottom:20px}.section-title>svg{width:28px;color:var(--color-primary)}.section-title h2{margin:4px 0}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field-grid label{display:grid;gap:7px;font-weight:750}.field-grid input,.field-grid textarea{width:100%;border:1px solid var(--border);border-radius:12px;padding:11px 12px;background:var(--surface);color:var(--text);font:inherit}.field-grid input:focus,.field-grid textarea:focus{outline:3px solid var(--focus-ring);border-color:var(--color-primary)}.field-grid small{color:var(--text-muted);font-weight:500}.wide{grid-column:1/-1}.periods,.memory{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:18px}.periods span,.memory span{display:grid;gap:3px;padding:12px;border-radius:12px;background:var(--surface-soft)}.periods small,.memory small,.threshold small{color:var(--text-muted)}.toggle{display:flex;align-items:flex-start;gap:12px;padding:14px;border:1px solid var(--border);border-radius:14px}.toggle>input{margin-top:4px}.toggle>span{display:grid;gap:6px}.toggle small{display:block;margin-left:18px;color:var(--text-muted);line-height:1.5}.threshold{display:grid;grid-template-columns:1fr auto;gap:10px;margin-top:18px;padding:16px;border-radius:14px;background:var(--surface-soft)}.threshold>div{display:grid}.threshold>strong{font-size:1.3rem;color:var(--color-primary)}.threshold input{grid-column:1/-1;width:100%}.explain{color:var(--text-muted);line-height:1.6}.owl-intro{color:var(--text-muted);margin:-4px 0 16px}.owl-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.owl-option{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;padding:14px;border:1px solid var(--border);border-radius:16px;background:linear-gradient(145deg,var(--surface),var(--surface-soft));cursor:pointer;transition:transform var(--transition-fast),border-color var(--transition-fast),box-shadow var(--transition-fast)}.owl-option:hover:not(.disabled){transform:translateY(-2px);border-color:color-mix(in srgb,var(--color-primary) 24%,var(--border));box-shadow:var(--shadow-sm)}.owl-option.disabled{opacity:.5;cursor:not-allowed}.owl-option>span:nth-child(2){display:grid;gap:3px}.owl-option small{color:var(--text-muted);line-height:1.45}.owl-option input{width:20px;height:20px;accent-color:var(--color-primary)}.option-icon{width:40px;height:40px;border-radius:13px;display:grid;place-items:center}.option-icon svg{width:20px}.option-icon.violet{background:var(--wash-violet);color:var(--color-primary)}.option-icon.sky{background:var(--wash-sky);color:var(--color-sky)}.option-icon.mint{background:var(--wash-mint);color:var(--color-mint)}.option-icon.coral{background:var(--wash-coral);color:var(--color-coral)}.option-icon.sun{background:var(--wash-sun);color:var(--color-warning)}.instant-note{margin-top:14px;padding:11px 13px;border-radius:12px;background:var(--wash-mint);color:var(--color-success);font-weight:750}.save-bar{position:sticky;bottom:12px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 14px;border:1px solid var(--border);border-radius:14px;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(10px);box-shadow:var(--shadow-md)}.save-bar>span{color:var(--text-muted);font-size:.85rem}.save-bar svg{width:18px}@media(max-width:800px){.field-grid{grid-template-columns:1fr}.wide{grid-column:auto}.periods,.memory,.owl-options{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.owl-options{grid-template-columns:1fr}}@media(max-width:540px){.periods,.memory{grid-template-columns:1fr}.save-bar{align-items:stretch;flex-direction:column}.save-bar :deep(button){width:100%}}</style>
